/* catgirls.zone/testdata — reproducible fake data.
 *
 * The point is the seed: the same seed and the same settings always produce
 * the same rows, so a fixture generated here can be regenerated by anyone with
 * the link and does not have to be committed as a blob.
 */
(function () {
  "use strict";

  var $ = UI.$, el = UI.el;
  UI.boot("test data");

  /* ---------- seeded randomness ---------- */

  function hash(str) {
    var h = 0x811c9dc5;
    for (var i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h >>> 0;
  }

  function rng(seed) {
    var a = seed >>> 0;
    return function () {
      a = (a + 0x6d2b79f5) >>> 0;
      var t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  /* ---------- pools ---------- */

  var POOLS = {
    de: {
      first: ("Anna Lukas Mia Felix Emma Jonas Lena Paul Sophie Elias Marie Noah Lea Ben Hannah " +
        "Leon Clara Finn Emilia Luis Frieda Moritz Ida Oskar Greta Theo Johanna Karl Mathilda " +
        "Jakob Charlotte Anton Nele Philipp Alina Tobias Katrin Stefan Birgit Ralf").split(" "),
      last: ("Müller Schmidt Schneider Fischer Weber Meyer Wagner Becker Schulz Hoffmann Koch " +
        "Bauer Richter Klein Wolf Neumann Schwarz Zimmermann Braun Krüger Hofmann Lange Werner " +
        "Krause Lehmann Schmitt Meier Schulze Maier Köhler Herrmann König Walter Peters Möller").split(" "),
      city: ("Berlin Hamburg München Köln Frankfurt Stuttgart Düsseldorf Leipzig Dortmund Essen " +
        "Bremen Dresden Hannover Nürnberg Bochum Wuppertal Bielefeld Bonn Münster Karlsruhe " +
        "Mannheim Augsburg Wiesbaden Kiel Freiburg Erfurt Rostock Jena Potsdam Regensburg").split(" "),
      street: ("Hauptstraße Bahnhofstraße Gartenstraße Schulstraße Dorfstraße Lindenstraße " +
        "Bergstraße Kirchstraße Waldstraße Ringstraße Amselweg Birkenweg Feldstraße Mühlenweg " +
        "Rosenstraße Poststraße Schillerstraße Goethestraße Talstraße Brunnenweg").split(" "),
      company: ("Nordwind Kranich Silberbach Hafenlicht Waldhaus Tannenberg Eisenwerk Blauhaus " +
        "Steinfeld Morgenrot Kupferrohr Lichtblick Sonnenhof Feldmann Rheintal").split(" "),
      suffix: ["GmbH", "AG", "GmbH & Co. KG", "SE", "e.K."],
      job: ("Entwicklerin Vertriebsleiter Buchhalterin Projektleiter Designerin Einkäufer " +
        "Personalreferentin Techniker Redakteurin Controller Logistikerin Architekt " +
        "Datenanalystin Hausmeister Beraterin").split(" "),
      country: "Deutschland",
      iban: "DE",
      phone: function (r) {
        return "+49 " + (150 + Math.floor(r() * 30)) + " " + digits(r, 7);
      },
      postcode: function (r) { return digits(r, 5); },
      tld: ["de", "de", "de", "com", "net"]
    },
    en: {
      first: ("Olivia Liam Emma Noah Ava Oliver Sophia Elijah Isabella James Mia Benjamin " +
        "Charlotte Lucas Amelia Henry Harper Alexander Evelyn Daniel Grace Samuel Chloe Owen " +
        "Ruby Jack Alice Thomas Nora Isaac Freya George Iris Arthur Maya").split(" "),
      last: ("Smith Johnson Williams Brown Jones Garcia Miller Davis Wilson Anderson Taylor " +
        "Thomas Moore Jackson Martin Lee Clark Lewis Walker Hall Allen Young Wright Scott " +
        "Green Baker Adams Nelson Hill Campbell Mitchell Roberts Carter Phillips Evans").split(" "),
      city: ("London Manchester Bristol Leeds Glasgow Edinburgh Liverpool Sheffield Cardiff " +
        "Belfast Brighton Oxford Cambridge York Bath Norwich Exeter Dundee Newcastle Nottingham " +
        "Portland Austin Denver Seattle Boston Chicago Atlanta Phoenix Madison Boulder").split(" "),
      street: ("High Street|Church Lane|Station Road|Victoria Road|Mill Lane|Park Avenue|" +
        "Queens Road|Kings Road|Green Lane|New Street|Elm Street|Maple Avenue|Oak Drive|" +
        "Cedar Close|Willow Way|Bridge Street|Market Square|Chapel Street|Albert Road|" +
        "West End").split("|"),
      company: ("Northwind Kestrel Silverbrook Harbourlight Woodhouse Ironworks Bluehouse " +
        "Stonefield Daybreak Copperpipe Brightside Sunfield Fieldman Rivervale Longmoor").split(" "),
      suffix: ["Ltd", "LLC", "Inc.", "PLC", "& Co."],
      job: ("Developer|Sales Lead|Accountant|Project Manager|Designer|Buyer|HR Partner|" +
        "Technician|Editor|Controller|Logistics Planner|Architect|Data Analyst|Caretaker|" +
        "Consultant").split("|"),
      country: "United Kingdom",
      iban: "GB",
      phone: function (r) { return "+44 7" + digits(r, 3) + " " + digits(r, 6); },
      postcode: function (r) {
        var L = "ABDEFGHJLNPQRSTUWXYZ";
        return L[Math.floor(r() * L.length)] + L[Math.floor(r() * L.length)] +
          digits(r, 1) + " " + digits(r, 1) +
          L[Math.floor(r() * L.length)] + L[Math.floor(r() * L.length)];
      },
      tld: ["co.uk", "com", "com", "org", "io"]
    }
  };

  var LOREM = ("the quick cat sat on a warm windowsill and watched rain fall across the yard " +
    "while somewhere a kettle whistled and the afternoon went quietly by without asking " +
    "anything of anyone at all").split(" ");

  function digits(r, n) {
    var s = "";
    for (var i = 0; i < n; i++) s += Math.floor(r() * 10);
    return s;
  }

  function pickOne(r, arr) { return arr[Math.floor(r() * arr.length)]; }

  /* ---------- IBAN ---------- */

  var IBAN_LEN = { DE: 22, AT: 20, CH: 21, NL: 18, FR: 27, GB: 22 };

  // mod-97 taken digit by digit: the full number is far past what a double can
  // hold, so it has to be reduced as it goes.
  function mod97(s) {
    var rem = 0;
    for (var i = 0; i < s.length; i++) {
      var ch = s[i];
      var v = ch >= "0" && ch <= "9" ? ch : String(ch.charCodeAt(0) - 55);
      for (var j = 0; j < v.length; j++) rem = (rem * 10 + (+v[j])) % 97;
    }
    return rem;
  }

  function makeIban(cc, r) {
    var body = "";
    while (body.length < IBAN_LEN[cc] - 4) body += Math.floor(r() * 10);
    if (cc === "GB") body = "ABCD" + body.slice(4);
    if (cc === "NL") body = "ABNA" + body.slice(4);
    var check = 98 - mod97(body + cc + "00");
    return cc + String(check).padStart(2, "0") + body;
  }

  function ibanValid(iban) {
    return mod97(iban.slice(4) + iban.slice(0, 4)) === 1;
  }

  /* ---------- fields ---------- */

  function slug(s) {
    return s.toLowerCase()
      .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
      .replace(/[^a-z0-9]+/g, "");
  }

  function uuid(r) {
    var h = "";
    for (var i = 0; i < 32; i++) h += Math.floor(r() * 16).toString(16);
    return h.slice(0, 8) + "-" + h.slice(8, 12) + "-4" + h.slice(13, 16) + "-" +
      "89ab"[Math.floor(r() * 4)] + h.slice(17, 20) + "-" + h.slice(20, 32);
  }

  var FIELDS = [
    ["id", "id (UUID v4)", true, function (r, P, ctx) { return uuid(r); }],
    ["firstName", "first name", true, function (r, P, ctx) { return ctx.first; }],
    ["lastName", "last name", true, function (r, P, ctx) { return ctx.last; }],
    ["fullName", "full name", false, function (r, P, ctx) { return ctx.first + " " + ctx.last; }],
    ["email", "email", true, function (r, P, ctx) {
      return slug(ctx.first) + "." + slug(ctx.last) + "@" +
        slug(ctx.company) + "." + pickOne(r, P.tld);
    }],
    ["username", "username", false, function (r, P, ctx) {
      return slug(ctx.first) + slug(ctx.last).slice(0, 3) + Math.floor(r() * 900 + 100);
    }],
    ["phone", "phone", false, function (r, P) { return P.phone(r); }],
    ["birthdate", "birth date", false, function (r) {
      var y = 1955 + Math.floor(r() * 55);
      var m = 1 + Math.floor(r() * 12);
      var d = 1 + Math.floor(r() * 28);
      return y + "-" + String(m).padStart(2, "0") + "-" + String(d).padStart(2, "0");
    }],
    ["street", "street", false, function (r, P) {
      return pickOne(r, P.street) + " " + (1 + Math.floor(r() * 180));
    }],
    ["postcode", "postcode", false, function (r, P) { return P.postcode(r); }],
    ["city", "city", false, function (r, P) { return pickOne(r, P.city); }],
    ["country", "country", false, function (r, P) { return P.country; }],
    ["company", "company", false, function (r, P, ctx) { return ctx.company; }],
    ["jobTitle", "job title", false, function (r, P) { return pickOne(r, P.job); }],
    ["iban", "IBAN (valid checksum)", false, function (r, P) { return makeIban(P.iban, r); }],
    ["sentence", "sentence", false, function (r) {
      var n = 5 + Math.floor(r() * 8), out = [];
      for (var i = 0; i < n; i++) out.push(pickOne(r, LOREM));
      return out.join(" ").replace(/^./, function (c) { return c.toUpperCase(); }) + ".";
    }],
    ["active", "boolean", false, function (r) { return r() < 0.72; }],
    ["score", "integer 0–100", false, function (r) { return Math.floor(r() * 101); }],
    ["price", "price", false, function (r) { return Math.round(r() * 25000) / 100; }],
    ["createdAt", "created at (ISO)", false, function (r) {
      var ms = Date.UTC(2023, 0, 1) + Math.floor(r() * 3 * 365 * 86400000);
      return new Date(ms).toISOString();
    }]
  ];

  /* ---------- generation ---------- */

  function generate() {
    var seed = $("#seed").value || "seed";
    var count = Math.max(1, Math.min(1000, Math.floor(+$("#count").value) || 1));
    var locale = $("#locale").value;
    var P = POOLS[locale];
    var chosen = FIELDS.filter(function (f) {
      var box = $("#f-" + f[0]);
      return box && box.checked;
    });

    var rows = [];
    for (var i = 0; i < count; i++) {
      // One stream per row, keyed by seed and index, so changing the count
      // never reshuffles the rows that were already there.
      var r = rng(hash(seed + "#" + i));
      var ctx = {
        first: pickOne(r, P.first),
        last: pickOne(r, P.last),
        company: pickOne(r, P.company)
      };
      ctx.company = ctx.company + " " + pickOne(r, P.suffix);
      var row = {};
      chosen.forEach(function (f) { row[f[0]] = f[3](r, P, ctx); });
      rows.push(row);
    }
    return { rows: rows, fields: chosen.map(function (f) { return f[0]; }) };
  }

  /* ---------- formats ---------- */

  function csvCell(v) {
    var s = String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  function sqlLiteral(v) {
    if (typeof v === "number") return String(v);
    if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
    return "'" + String(v).replace(/'/g, "''") + "'";
  }

  function render(data, format) {
    var rows = data.rows, fields = data.fields;
    if (!fields.length) return "Pick at least one field.";
    switch (format) {
      case "json": return JSON.stringify(rows, null, 2);
      case "ndjson": return rows.map(function (r) { return JSON.stringify(r); }).join("\n");
      case "csv":
        return [fields.join(",")].concat(rows.map(function (r) {
          return fields.map(function (f) { return csvCell(r[f]); }).join(",");
        })).join("\n");
      case "sql":
        var table = ($("#table").value || "people").replace(/[^A-Za-z0-9_]/g, "");
        return rows.map(function (r) {
          return "INSERT INTO " + table + " (" + fields.join(", ") + ") VALUES (" +
            fields.map(function (f) { return sqlLiteral(r[f]); }).join(", ") + ");";
        }).join("\n");
      default: return "";
    }
  }

  /* ---------- ui ---------- */

  function buildFields() {
    var host = $("#fields");
    FIELDS.forEach(function (f) {
      var box = el("input", { type: "checkbox", id: "f-" + f[0], style: "width:auto" });
      box.checked = f[2];
      box.addEventListener("change", run);
      host.appendChild(el("label", { class: "row small", style: "gap:6px;margin:0" }, [box, f[1]]));
    });
  }

  var current = "";

  function run() {
    var data = generate();
    var format = $("#format").value;
    $("#table-wrap").hidden = format !== "sql";
    current = render(data, format);
    $("#out").textContent = current;
    $("#stat").textContent = data.rows.length + " rows · " + data.fields.length +
      " fields · " + current.length.toLocaleString("en-US") + " characters";
    syncUrl();
  }

  // The whole configuration lives in the URL, so a fixture is shareable as a
  // link instead of a committed file.
  function syncUrl() {
    var on = FIELDS.filter(function (f) { return $("#f-" + f[0]).checked; })
                   .map(function (f) { return f[0]; });
    var url = new URL(location.href);
    url.hash = "";
    url.search = "";
    url.searchParams.set("seed", $("#seed").value);
    url.searchParams.set("n", $("#count").value);
    url.searchParams.set("l", $("#locale").value);
    url.searchParams.set("f", on.join(","));
    url.searchParams.set("fmt", $("#format").value);
    history.replaceState(null, "", url);
  }

  function fromUrl() {
    var q = new URLSearchParams(location.search);
    if (q.get("seed")) $("#seed").value = q.get("seed");
    if (q.get("n")) $("#count").value = q.get("n");
    if (q.get("l") && POOLS[q.get("l")]) $("#locale").value = q.get("l");
    if (q.get("fmt")) $("#format").value = q.get("fmt");
    var f = q.get("f");
    if (f !== null) {
      var want = f.split(",");
      FIELDS.forEach(function (fd) {
        $("#f-" + fd[0]).checked = want.indexOf(fd[0]) >= 0;
      });
    }
  }

  ["#seed", "#count", "#locale", "#format", "#table"].forEach(function (s) {
    $(s).addEventListener("input", run);
    $(s).addEventListener("change", run);
  });

  $("#reroll").addEventListener("click", function () {
    $("#seed").value = Math.random().toString(36).slice(2, 10);
    run();
  });

  $("#copy").addEventListener("click", function () { UI.copy(current, "Data"); });

  $("#share").addEventListener("click", function () { UI.copy(location.href, "Link"); });

  $("#download").addEventListener("click", function () {
    var ext = { json: "json", ndjson: "ndjson", csv: "csv", sql: "sql" }[$("#format").value];
    var blob = new Blob([current], { type: "text/plain" });
    var a = el("a", { href: URL.createObjectURL(blob), download: "testdata." + ext });
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 1000);
  });

  $("#all").addEventListener("click", function () {
    FIELDS.forEach(function (f) { $("#f-" + f[0]).checked = true; });
    run();
  });

  $("#none").addEventListener("click", function () {
    FIELDS.forEach(function (f) { $("#f-" + f[0]).checked = false; });
    run();
  });

  buildFields();
  fromUrl();
  run();

  window.__testdata = { makeIban: makeIban, ibanValid: ibanValid, generate: generate,
                        render: render, IBAN_LEN: IBAN_LEN };
})();
